 59	static int ascii_space(char c)
 60	{
 61	    return c == ' ' || c == '\t' || c == '\r' || c == '\n';
 62	}
 63	
 64	static int identifier_start(char c)
 65	{
 66	    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_' || c == ':';
 67	}
 68	
 69	static int identifier_part(char c)
 70	{
 71	    return identifier_start(c) || (c >= '0' && c <= '9') || c == '.' || c == '-';
 72	}
 73	
 74	int markup_lex(const char *source, size_t length, Markup *markup, Diagnostic *diagnostic)
 75	{
 76	    size_t offset = 0;
 77	    Location loc = {0, 1, 1};
 78	    int in_tag = 0;
 79	    memset(markup, 0, sizeof(*markup));
 80	    memset(diagnostic, 0, sizeof(*diagnostic));
 81	    while (offset < length) {
 82	        char c = source[offset];
 83	        Location start = loc;
 84	        size_t begin;
 85	        if ((unsigned char)c < 0x20 && !ascii_space(c)) {
 86	            diagnostic_set(diagnostic, loc, "invalid byte in markup");
 87	            markup_free(markup);
 88	            return -1;
 89	        }
 90	        if ((unsigned char)c >= 0x7f) {
 91	            diagnostic_set(diagnostic, loc, "invalid byte in markup");
 92	            markup_free(markup);
 93	            return -1;
 94	        }
 95	        if (!in_tag) {
 96	            if (c == '<') {
 97	                if (add_token(markup, MARKUP_LITERAL, "<", 1, start) != 0)
 98	                    goto out_of_memory;
 99	                move_location(&loc, c, &offset);
100	                in_tag = 1;
101	            } else {
102	                begin = offset;
103	                {
104	                    int all_whitespace = 1;
105	                    while (offset < length && source[offset] != '<') {
106	                    c = source[offset];
107	                    if (((unsigned char)c < 0x20 && !ascii_space(c)) || (unsigned char)c >= 0x7f) {
108	                        diagnostic_set(diagnostic, loc, "invalid byte in markup");
109	                        markup_free(markup);
110	                        return -1;
111	                    }
112	                    if (!ascii_space(c))
113	                        all_whitespace = 0;
114	                    move_location(&loc, c, &offset);
115	                    }
116	                    if (!all_whitespace && add_token(markup, MARKUP_TEXT, source + begin,
117	                                                     offset - begin, start) != 0)
118	                        goto out_of_memory;
119	                }
120	            }
121	            continue;
122	        }
123	        if (ascii_space(c)) {
124	            move_location(&loc, c, &offset);
125	            continue;
126	        }
127	        if (c == '<' || c == '>' || c == '/' || c == '=') {
128	            if (add_token(markup, MARKUP_LITERAL, &c, 1, start) != 0)
129	                goto out_of_memory;
130	            move_location(&loc, c, &offset);
131	            if (c == '>')
132	                in_tag = 0;
133	            continue;
134	        }
135	        if (c == '\'' || c == '"') {
136	            char quote = c;
137	            size_t out = 0;
138	            char *value = (char *)malloc(1);
139	            if (value == NULL)
140	                goto out_of_memory;
141	            move_location(&loc, c, &offset);
142	            while (offset < length && source[offset] != quote) {
143	                c = source[offset];
144	                if (c == '\\') {
145	                    move_location(&loc, c, &offset);
146	                    if (offset == length || (source[offset] != quote && source[offset] != '\\')) {
147	                        free(value);
148	                        diagnostic_set(diagnostic, loc, "invalid string escape in markup");
149	                        markup_free(markup);
150	                        return -1;
151	                    }
152	                    c = source[offset];
153	                }
154	                if ((unsigned char)c < 0x20 || (unsigned char)c >= 0x7f) {
155	                    free(value);
156	                    diagnostic_set(diagnostic, loc, "invalid byte in markup string");
157	                    markup_free(markup);
158	                    return -1;
159	                }
160	                {
161	                    char *grown = (char *)realloc(value, out + 2);
162	                    if (grown == NULL) {
163	                        free(value);
164	                        goto out_of_memory;
165	                    }
166	                    value = grown;
167	                }
168	                value[out++] = c;
169	                value[out] = '\0';
170	                move_location(&loc, c, &offset);
171	            }
172	            if (offset == length) {
173	                free(value);
174	                diagnostic_set(diagnostic, start, "unterminated markup string");
175	                markup_free(markup);
176	                return -1;
177	            }
178	            move_location(&loc, quote, &offset);
179	            if (grow_tokens(markup) != 0) {
180	                free(value);
181	                goto out_of_memory;
182	            }
183	            markup->tokens[markup->count++] = (MarkupToken){MARKUP_STRING, value, start};
184	            continue;
185	        }
186	        if (identifier_start(c)) {
187	            begin = offset;
188	            move_location(&loc, c, &offset);
189	            while (offset < length && identifier_part(source[offset]))
190	                move_location(&loc, source[offset], &offset);
191	            if (add_token(markup, MARKUP_IDENT, source + begin, offset - begin, start) != 0)
192	                goto out_of_memory;
193	            continue;
194	        }
195	        diagnostic_set(diagnostic, loc, "invalid character in markup tag");
196	        markup_free(markup);
197	        return -1;
198	    }
199	    if (in_tag) {
200	        diagnostic_set(diagnostic, loc, "unterminated markup tag");
201	        markup_free(markup);
202	        return -1;
203	    }
204	    return 0;
205	
206	out_of_memory:
207	    diagnostic_set(diagnostic, loc, "out of memory");
208	    markup_free(markup);
209	    return -1;
210	}
211	
212	void markup_free(Markup *markup)
213	{
214	    size_t i;
215	    for (i = 0; i < markup->count; i++)
216	        free(markup->tokens[i].lexeme);
217	    free(markup->tokens);
218	    memset(markup, 0, sizeof(*markup));
219	}
