  5	static void *worker_main(void *arg)
  6	{
  7	    PoolWorkerArg *worker = (PoolWorkerArg *)arg;
  8	    WorkerPool *pool = worker->pool;
  9	    size_t index = worker->index;
 10	    unsigned long seen = 0;
 11	
 12	    for (;;) {
 13	        pthread_mutex_lock(&pool->mutex);
 14	        while (!pool->stopping && seen == pool->generation)
 15	            pthread_cond_wait(&pool->work_ready, &pool->mutex);
 16	        if (pool->stopping) {
 17	            pthread_mutex_unlock(&pool->mutex);
 18	            return NULL;
 19	        }
 20	        seen = pool->generation;
 21	        pthread_mutex_unlock(&pool->mutex);
 22	
 23	        if (pool->task != NULL && pool->ends[index] > pool->begins[index])
 24	            pool->task(pool->context, index, pool->begins[index], pool->ends[index]);
 25	
 26	        pthread_mutex_lock(&pool->mutex);
 27	        pool->completed++;
 28	        if (pool->completed == 8)
 29	            pthread_cond_signal(&pool->done);
 30	        pthread_mutex_unlock(&pool->mutex);
 31	    }
 32	}
 33	
 34	int pool_start(WorkerPool *pool)
 35	{
 36	    size_t i;
 37	    pool->generation = 0;
 38	    pool->stopping = 0;
 39	    pool->task_count = 0;
 40	    pool->completed = 0;
 41	    pool->task = NULL;
 42	    pool->context = NULL;
 43	    pool->begins = (size_t *)calloc(8, sizeof(*pool->begins));
 44	    pool->ends = (size_t *)calloc(8, sizeof(*pool->ends));
 45	    if (pool->begins == NULL || pool->ends == NULL) {
 46	        free(pool->begins);
 47	        free(pool->ends);
 48	        return -1;
 49	    }
 50	    if (pthread_mutex_init(&pool->mutex, NULL) != 0)
 51	        goto fail_arrays;
 52	    if (pthread_cond_init(&pool->work_ready, NULL) != 0)
 53	        goto fail_mutex;
 54	    if (pthread_cond_init(&pool->done, NULL) != 0)
 55	        goto fail_work;
 56	    pool->initialized = 1;
 57	    for (i = 0; i < 8; i++) {
 58	        pool->worker_args[i].pool = pool;
 59	        pool->worker_args[i].index = i;
 60	        if (pthread_create(&pool->threads[i], NULL, worker_main, &pool->worker_args[i]) != 0) {
 61	            size_t j;
 62	            pthread_mutex_lock(&pool->mutex);
 63	            pool->stopping = 1;
 64	            pthread_cond_broadcast(&pool->work_ready);
 65	            pthread_mutex_unlock(&pool->mutex);
 66	            for (j = 0; j < i; j++)
 67	                pthread_join(pool->threads[j], NULL);
 68	            pthread_cond_destroy(&pool->done);
 69	            pthread_cond_destroy(&pool->work_ready);
 70	            pthread_mutex_destroy(&pool->mutex);
 71	            pool->initialized = 0;
 72	            goto fail_arrays;
 73	        }
 74	    }
 75	    return 0;
 76	
 77	fail_work:
 78	    pthread_cond_destroy(&pool->work_ready);
 79	fail_mutex:
 80	    pthread_mutex_destroy(&pool->mutex);
 81	fail_arrays:
 82	    free(pool->begins);
 83	    free(pool->ends);
 84	    pool->begins = NULL;
 85	    pool->ends = NULL;
 86	    return -1;
 87	}
 88	
 89	int pool_run(WorkerPool *pool, size_t count, PoolTask task, void *context)
 90	{
 91	    size_t i;
 92	    if (count == 0)
 93	        count = 1;
 94	    pthread_mutex_lock(&pool->mutex);
 95	    pool->task_count = count;
 96	    pool->task = task;
 97	    pool->context = context;
 98	    pool->completed = 0;
 99	    for (i = 0; i < 8; i++) {
100	        pool->begins[i] = (count * i) / 8;
101	        pool->ends[i] = (count * (i + 1)) / 8;
102	    }
103	    pool->generation++;
104	    pthread_cond_broadcast(&pool->work_ready);
105	    while (pool->completed != 8)
106	        pthread_cond_wait(&pool->done, &pool->mutex);
107	    pthread_mutex_unlock(&pool->mutex);
108	    return 0;
109	}
110	
111	void pool_stop(WorkerPool *pool)
112	{
113	    size_t i;
114	    if (!pool->initialized)
115	        return;
116	    pthread_mutex_lock(&pool->mutex);
117	    pool->stopping = 1;
118	    pthread_cond_broadcast(&pool->work_ready);
119	    pthread_mutex_unlock(&pool->mutex);
120	    for (i = 0; i < 8; i++)
121	        pthread_join(pool->threads[i], NULL);
122	    pthread_cond_destroy(&pool->done);
123	    pthread_cond_destroy(&pool->work_ready);
124	    pthread_mutex_destroy(&pool->mutex);
125	    free(pool->begins);
126	    free(pool->ends);
127	    pool->begins = NULL;
128	    pool->ends = NULL;
129	    pool->initialized = 0;
130	}

220	    return 0;
221	}
