252	static size_t find_rule(const Grammar *grammar, const char *name)
253	{
254	    size_t i;
255	    for (i = 0; i < grammar->rule_count; i++)
256	        if (strcmp(grammar->rules[i].name, name) == 0)
257	            return i;
258	    return (size_t)-1;
