261	static int token_kind_from_name(const char *name, GrammarTokenKind *kind)
262	{
263	    if (strcmp(name, "IDENT") == 0) *kind = TOK_IDENT;
264	    else if (strcmp(name, "STRING") == 0) *kind = TOK_STRING;
265	    else if (strcmp(name, "TEXT") == 0) *kind = TOK_TEXT;
266	    else return -1;
267	    return 0;
268	}
