270	static int parse_directives(GrammarParser *parser)
271	{
272	    if (parser->current.kind != G_PERCENT || strcmp(parser->current.text, "start") != 0) {
273	        parse_error(parser, "first directive must be %start NAME");
274	        return -1;
275	    }
276	    if (parser_advance(parser) != 0 || parser->current.kind != G_IDENT) {
277	        parse_error(parser, "expected start rule name");
278	        return -1;
279	    }
280	    parser->grammar->start_name = copy_text(parser->current.text, strlen(parser->current.text));
281	    if (parser->grammar->start_name == NULL) {
282	        parse_error(parser, "out of memory");
283	        return -1;
284	    }
285	    if (parser_advance(parser) != 0)
286	        return -1;
287	    while (parser->current.kind == G_PERCENT) {
288	        GrammarTokenKind kind;
289	        if (strcmp(parser->current.text, "token") != 0) {
290	            parse_error(parser, "unknown directive");
291	            return -1;
292	        }
293	        if (parser_advance(parser) != 0 || parser->current.kind != G_IDENT) {
294	            parse_error(parser, "expected token kind");
295	            return -1;
296	        }
297	        if (token_kind_from_name(parser->current.text, &kind) != 0) {
298	            parse_error(parser, "token kind must be IDENT, STRING, or TEXT");
299	            return -1;
300	        }
301	        if (parser->grammar->declared_tokens[kind]) {
302	            parse_error(parser, "duplicate token declaration");
303	            return -1;
304	        }
305	        parser->grammar->declared_tokens[kind] = 1;
306	        if (parser_advance(parser) != 0)
307	            return -1;
308	    }
309	    return 0;
310	}
311	
312	static int parse_rules(GrammarParser *parser)
313	{
314	    while (parser->current.kind == G_IDENT) {
315	        Rule *rule;
316	        if (find_rule(parser->grammar, parser->current.text) != (size_t)-1) {
317	            parse_error(parser, "duplicate rule");
318	            return -1;
319	        }
320	        if (append_rule(parser->grammar, &rule) != 0) {
321	            parse_error(parser, "out of memory");
322	            return -1;
323	        }
324	        rule->name = copy_text(parser->current.text, strlen(parser->current.text));
325	        if (rule->name == NULL) {
326	            parse_error(parser, "out of memory");
327	            return -1;
328	        }
329	        if (parser_advance(parser) != 0 || parser->current.kind != G_ASSIGN) {
330	            parse_error(parser, "expected ::= after rule name");
331	            return -1;
332	        }
333	        if (parser_advance(parser) != 0)
334	            return -1;
335	        for (;;) {
336	            Alternative *alternative;
337	            if (append_alternative(rule, &alternative) != 0) {
338	                parse_error(parser, "out of memory");
339	                return -1;
340	            }
341	            while (parser->current.kind == G_IDENT || parser->current.kind == G_STRING ||
342	                   parser->current.kind == G_DOLLAR) {
343	                GrammarSymbol symbol;
344	                memset(&symbol, 0, sizeof(symbol));
345	                if (parser->current.kind == G_IDENT) {
346	                    symbol.kind = SYM_NONTERM;
347	                    symbol.text = copy_text(parser->current.text, strlen(parser->current.text));
348	                } else if (parser->current.kind == G_STRING) {
349	                    symbol.kind = SYM_LITERAL;
350	                    symbol.text = copy_text(parser->current.text, strlen(parser->current.text));
351	                } else {
352	                    GrammarTokenKind kind;
353	                    if (parser_advance(parser) != 0 || parser->current.kind != G_IDENT) {
354	                        parse_error(parser, "expected token kind after $");
355	                        return -1;
356	                    }
357	                    if (token_kind_from_name(parser->current.text, &kind) != 0 ||
358	                        !parser->grammar->declared_tokens[kind]) {
359	                        parse_error(parser, "$ reference uses an undeclared token kind");
360	                        return -1;
361	                    }
362	                    symbol.kind = SYM_TOKEN;
363	                    symbol.token_kind = kind;
364	                }
365	                if (symbol.kind != SYM_TOKEN && symbol.text == NULL) {
366	                    parse_error(parser, "out of memory");
367	                    return -1;
368	                }
369	                if (append_symbol(alternative, symbol) != 0) {
370	                    free(symbol.text);
371	                    parse_error(parser, "out of memory");
372	                    return -1;
373	                }
374	                if (parser_advance(parser) != 0)
375	                    return -1;
376	            }
377	            if (parser->current.kind == G_PIPE) {
378	                if (parser_advance(parser) != 0)
379	                    return -1;
380	                continue;
381	            }
382	            if (parser->current.kind != G_SEMI) {
383	                parse_error(parser, "expected | or ; in production");
384	                return -1;
385	            }
386	            if (parser_advance(parser) != 0)
387	                return -1;
388	            break;
389	        }
390	    }
391	    if (parser->grammar->rule_count == 0) {
392	        parse_error(parser, "grammar has no productions");
393	        return -1;
394	    }
395	    if (parser->current.kind != G_EOF) {
396	        parse_error(parser, "unexpected grammar input");
397	        return -1;
398	    }
399	    return 0;
400	}
