 50	static int vector_grow(ChartItem **data, size_t *capacity, size_t needed)
 51	{
 52	    size_t next = *capacity == 0 ? 16 : *capacity * 2;
 53	    ChartItem *grown;
 54	    if (*capacity >= needed)
 55	        return 0;
 56	    while (next < needed) {
 57	        if (next > ((size_t)-1) / 2)
 58	            return -1;
 59	        next *= 2;
 60	    }
 61	    grown = (ChartItem *)realloc(*data, next * sizeof(*grown));
 62	    if (grown == NULL)
 63	        return -1;
 64	    *data = grown;
 65	    *capacity = next;
 66	    return 0;
 67	}
 68	
 69	static int add_item(ItemVector *vector, ChartItem item)
 70	{
 71	    size_t i;
 72	    for (i = 0; i < vector->count; i++)
 73	        if (item_equal(&vector->data[i], &item))
 74	            return 0;
 75	    if (vector_grow(&vector->data, &vector->capacity, vector->count + 1) != 0)
 76	        return -1;
 77	    vector->data[vector->count++] = item;
 78	    return 1;
 79	}
 80	
 81	static int add_candidate(CandidateVector *vector, ChartItem item, atomic_int *failed)
 82	{
 83	    if (vector_grow(&vector->data, &vector->capacity, vector->count + 1) != 0) {
 84	        atomic_store(failed, 1);
 85	        return -1;
 86	    }
 87	    vector->data[vector->count++] = item;
 88	    return 0;
 89	}
