 91	static size_t rule_index(const Grammar *grammar, const char *name)
 92	{
 93	    size_t i;
 94	    for (i = 0; i < grammar->rule_count; i++)
 95	        if (strcmp(grammar->rules[i].name, name) == 0)
 96	            return i;
 97	    return (size_t)-1;
 98	}
