100	static const GrammarSymbol *next_symbol(const Grammar *grammar, const ChartItem *item)
101	{
102	    const Alternative *alternative = &grammar->rules[item->rule].alternatives[item->alternative];
103	    if (item->dot >= alternative->count)
104	        return NULL;
105	    return &alternative->symbols[item->dot];
106	}
