108	static void closure_task(void *context, size_t worker, size_t begin, size_t end)
109	{
110	    ClosureWork *work = (ClosureWork *)context;
111	    ItemVector *current = &work->charts[work->position];
112	    CandidateVector *out = &work->candidates[worker];
113	    size_t i;
114	    for (i = begin; i < end && !atomic_load(&work->failed); i++) {
115	        ChartItem item = current->data[i];
116	        const GrammarSymbol *symbol = next_symbol(work->grammar, &item);
117	        if (symbol != NULL && symbol->kind == SYM_NONTERM) {
118	            size_t target = rule_index(work->grammar, symbol->text);
119	            size_t j;
120	            for (j = 0; j < work->grammar->rules[target].count; j++) {
121	                ChartItem candidate = {target, j, 0, work->position};
122	                if (add_candidate(out, candidate, &work->failed) != 0)
123	                    return;
124	            }
125	        } else if (symbol == NULL) {
126	            size_t j;
127	            if (item.origin > work->position)
128	                continue;
129	            for (j = 0; j < work->charts[item.origin].count; j++) {
130	                ChartItem parent = work->charts[item.origin].data[j];
131	                const GrammarSymbol *wanted = next_symbol(work->grammar, &parent);
132	                if (wanted != NULL && wanted->kind == SYM_NONTERM &&
133	                    rule_index(work->grammar, wanted->text) == item.rule) {
134	                    ChartItem candidate = {parent.rule, parent.alternative, parent.dot + 1, parent.origin};
135	                    if (add_candidate(out, candidate, &work->failed) != 0)
136	                        return;
137	                }
138	            }
139	        }
140	    }
141	}
