143	static int token_matches(const GrammarSymbol *symbol, const MarkupToken *token)
144	{
145	    if (symbol->kind == SYM_LITERAL)
146	        return strcmp(symbol->text, token->lexeme) == 0;
147	    if (symbol->kind == SYM_TOKEN) {
148	        if (symbol->token_kind == TOK_IDENT) return token->kind == MARKUP_IDENT;
149	        if (symbol->token_kind == TOK_STRING) return token->kind == MARKUP_STRING;
150	        return token->kind == MARKUP_TEXT;
151	    }
152	    return 0;
153	}
