155	static void scan_task(void *context, size_t worker, size_t begin, size_t end)
156	{
157	    ScanWork *work = (ScanWork *)context;
158	    CandidateVector *out = &work->candidates[worker];
159	    size_t i;
160	    if (end > work->current->count)
161	        end = work->current->count;
162	    for (i = begin; i < end && !atomic_load(&work->failed); i++) {
163	        const ChartItem *item = &work->current->data[i];
164	        const GrammarSymbol *symbol = next_symbol(work->grammar, item);
165	        if (symbol != NULL && symbol->kind != SYM_NONTERM &&
166	            token_matches(symbol, &work->markup->tokens[work->position])) {
167	            ChartItem candidate = {item->rule, item->alternative, item->dot + 1, item->origin};
168	            if (add_candidate(out, candidate, &work->failed) != 0)
169	                return;
170	        }
171	    }
172	}
