185	static int merge_candidates(ItemVector *target, CandidateVector *vectors)
186	{
187	    size_t total = 0;
188	    size_t i;
189	    ChartItem *all;
190	    size_t at = 0;
191	    for (i = 0; i < 8; i++)
192	        total += vectors[i].count;
193	    if (total == 0)
194	        return 0;
195	    all = (ChartItem *)malloc(total * sizeof(*all));
196	    if (all == NULL)
197	        return -1;
198	    for (i = 0; i < 8; i++) {
199	        memcpy(all + at, vectors[i].data, vectors[i].count * sizeof(*all));
200	        at += vectors[i].count;
201	    }
202	    qsort(all, total, sizeof(*all), candidate_compare);
203	    for (i = 0; i < total; i++) {
204	        if (add_item(target, all[i]) < 0) {
205	            free(all);
206	            return -1;
207	        }
208	    }
209	    free(all);
210	    return 0;
211	}
