235	static void expected_add(char *expected, size_t capacity, const GrammarSymbol *symbol)
236	{
237	    char part[80];
238	    size_t used = strlen(expected);
239	    if (symbol->kind == SYM_LITERAL)
240	        (void)snprintf(part, sizeof(part), "'%s'", symbol->text);
241	    else if (symbol->token_kind == TOK_IDENT)
242	        (void)snprintf(part, sizeof(part), "$IDENT");
243	    else if (symbol->token_kind == TOK_STRING)
244	        (void)snprintf(part, sizeof(part), "$STRING");
245	    else
246	        (void)snprintf(part, sizeof(part), "$TEXT");
247	    if (used != 0 && used + 2 < capacity) {
248	        (void)strncat(expected, ", ", capacity - used - 1);
249	        used += 2;
250	    }
251	    if (used + strlen(part) + 1 < capacity)
252	        (void)strncat(expected, part, capacity - used - 1);
253	}
