255	int recognize(const Grammar *grammar, const Markup *markup, Recognition *result)
256	{
257	    WorkerPool pool;
258	    ItemVector *charts;
259	    CandidateVector candidates[8];
260	    size_t chart_count = markup->count + 1;
261	    size_t position;
262	    int pool_ok = 0;
263	    memset(result, 0, sizeof(*result));
264	    memset(&pool, 0, sizeof(pool));
265	    memset(candidates, 0, sizeof(candidates));
266	    charts = (ItemVector *)calloc(chart_count, sizeof(*charts));
267	    if (charts == NULL)
268	        return -1;
269	    if (pool_start(&pool) != 0) {
270	        free_charts(charts, chart_count);
271	        return -1;
272	    }
273	    pool_ok = 1;
274	    for (position = 0; position < grammar->rules[grammar->start_rule].count; position++) {
275	        ChartItem seed = {grammar->start_rule, position, 0, 0};
276	        if (add_item(&charts[0], seed) < 0)
277	            goto failed;
278	    }
279	    for (position = 0; position <= markup->count; position++) {
280	        size_t processed = 0;
281	        while (processed < charts[position].count) {
282	            ClosureWork work;
283	            size_t snapshot = charts[position].count;
284	            clear_candidates(candidates);
285	            work.grammar = grammar;
286	            work.charts = charts;
287	            work.position = position;
288	            work.candidates = candidates;
289	            atomic_init(&work.failed, 0);
290	            if (pool_run(&pool, snapshot, closure_task, &work) != 0 || atomic_load(&work.failed))
291	                goto failed;
292	            result->rounds++;
293	            if (merge_candidates(&charts[position], candidates) != 0)
294	                goto failed;
295	            processed = snapshot;
296	        }
297	        if (position < markup->count) {
298	            ScanWork work;
299	            clear_candidates(candidates);
300	            work.grammar = grammar;
301	            work.markup = markup;
302	            work.current = &charts[position];
303	            work.position = position;
304	            work.candidates = candidates;
305	            atomic_init(&work.failed, 0);
306	            if (pool_run(&pool, charts[position].count == 0 ? 1 : charts[position].count,
307	                         scan_task, &work) != 0 || atomic_load(&work.failed))
308	                goto failed;
309	            result->rounds++;
310	            if (merge_candidates(&charts[position + 1], candidates) != 0)
311	                goto failed;
312	        }
313	    }
314	    result->accepted = 0;
315	    {
316	        size_t i;
317	        for (i = 0; i < charts[markup->count].count; i++) {
318	            ChartItem item = charts[markup->count].data[i];
319	            if (item.rule == grammar->start_rule && item.origin == 0 &&
320	                next_symbol(grammar, &item) == NULL) {
321	                result->accepted = 1;
322	                break;
323	            }
324	        }
325	    }
326	    if (!result->accepted) {
327	        size_t furthest = 0;
328	        for (position = 0; position <= markup->count; position++) {
329	            size_t i;
330	            int active = 0;
331	            for (i = 0; i < charts[position].count; i++)
332	                if (next_symbol(grammar, &charts[position].data[i]) != NULL)
333	                    active = 1;
334	            if (active)
335	                furthest = position;
336	        }
337	        result->error_position = furthest;
338	        result->expected[0] = '\0';
339	        for (position = 0; position < charts[furthest].count; position++) {
340	            const GrammarSymbol *symbol = next_symbol(grammar, &charts[furthest].data[position]);
341	            if (symbol != NULL && symbol->kind != SYM_NONTERM)
342	                expected_add(result->expected, sizeof(result->expected), symbol);
343	        }
344	        if (result->expected[0] == '\0')
345	            (void)snprintf(result->expected, sizeof(result->expected), "markup token");
346	    }
347	    for (position = 0; position < 8; position++)
348	        result->tasks[position] = pool.generation;
349	    free_candidates(candidates);
350	    if (pool_ok)
351	        pool_stop(&pool);
352	    free_charts(charts, chart_count);
353	    return 0;
354	
355	failed:
356	    free_candidates(candidates);
357	    if (pool_ok)
358	        pool_stop(&pool);
359	    free_charts(charts, chart_count);
360	    return -1;
361	}
