 44	static void print_grammar_error(const char *what, const Diagnostic *diagnostic)
 45	{
 46	    if (diagnostic->present)
 47	        (void)fprintf(stdout, "GRAMMAR_ERROR %s offset=%zu line=%zu column=%zu %s\n",
 48	                      what, diagnostic->loc.offset, diagnostic->loc.line,
 49	                      diagnostic->loc.column, diagnostic->message);
 50	    else
 51	        (void)fprintf(stdout, "GRAMMAR_ERROR %s\n", what);
 52	}
