 54	static Location end_location(const char *source, size_t length)
 55	{
 56	    size_t i;
 57	    Location loc = {length, 1, 1};
 58	    for (i = 0; i < length; i++) {
 59	        if (source[i] == '\n') {
 60	            loc.line++;
 61	            loc.column = 1;
 62	        } else {
 63	            loc.column++;
 64	        }
 65	    }
 66	    return loc;
 67	}
