 69	int main(int argc, char **argv)
 70	{
 71	    const char *grammar_path = NULL;
 72	    const char *input_path = NULL;
 73	    const char *start_name = NULL;
 74	    int stats = 0;
 75	    char *grammar_source = NULL;
 76	    char *input_source = NULL;
 77	    size_t grammar_length = 0;
 78	    size_t input_length = 0;
 79	    Grammar grammar;
 80	    Markup markup;
 81	    Diagnostic diagnostic;
 82	    Recognition recognition;
 83	    int i;
 84	    int status;
 85	    memset(&diagnostic, 0, sizeof(diagnostic));
 86	    if (argc < 5) {
 87	        print_grammar_error("usage: bin/pbnfc --grammar PATH --input PATH [--start NAME] [--stats]", &diagnostic);
 88	        return 2;
 89	    }
 90	    for (i = 1; i < argc; i++) {
 91	        if (strcmp(argv[i], "--grammar") == 0 && i + 1 < argc)
 92	            grammar_path = argv[++i];
 93	        else if (strcmp(argv[i], "--input") == 0 && i + 1 < argc)
 94	            input_path = argv[++i];
 95	        else if (strcmp(argv[i], "--start") == 0 && i + 1 < argc)
 96	            start_name = argv[++i];
 97	        else if (strcmp(argv[i], "--stats") == 0)
 98	            stats = 1;
 99	        else {
100	            print_grammar_error("invalid command line", &diagnostic);
101	            return 2;
102	        }
103	    }
104	    if (grammar_path == NULL || input_path == NULL) {
105	        print_grammar_error("--grammar and --input are required", &diagnostic);
106	        return 2;
107	    }
108	    if (read_file(grammar_path, &grammar_source, &grammar_length) != 0) {
109	        (void)fprintf(stdout, "GRAMMAR_ERROR cannot read grammar: %s\n", grammar_path);
110	        return 2;
111	    }
112	    if (read_file(input_path, &input_source, &input_length) != 0) {
113	        free(grammar_source);
114	        (void)fprintf(stdout, "GRAMMAR_ERROR cannot read input: %s\n", input_path);
115	        return 2;
116	    }
117	    if (grammar_parse(grammar_source, grammar_length, &grammar, &diagnostic) != 0) {
118	        print_grammar_error("grammar", &diagnostic);
119	        free(grammar_source);
120	        free(input_source);
121	        return 2;
122	    }
123	    if (start_name != NULL && grammar_set_start(&grammar, start_name, &diagnostic) != 0) {
124	        print_grammar_error("grammar", &diagnostic);
125	        grammar_free(&grammar);
126	        free(grammar_source);
127	        free(input_source);
128	        return 2;
129	    }
130	    if (markup_lex(input_source, input_length, &markup, &diagnostic) != 0) {
131	        print_grammar_error("markup", &diagnostic);
132	        grammar_free(&grammar);
133	        free(grammar_source);
134	        free(input_source);
135	        return 2;
136	    }
137	    status = recognize(&grammar, &markup, &recognition);
138	    if (status != 0) {
139	        (void)fprintf(stdout, "GRAMMAR_ERROR recognizer failure\n");
140	        markup_free(&markup);
141	        grammar_free(&grammar);
142	        free(grammar_source);
143	        free(input_source);
144	        return 2;
145	    }
146	    if (recognition.accepted) {
147	        (void)fprintf(stdout, "ACCEPT tokens=%zu", markup.count);
148	        if (stats) {
149	            (void)fprintf(stdout, " workers=8 active_workers=8 rounds=%zu tasks=", recognition.rounds);
150	            for (i = 0; i < 8; i++)
151	                (void)fprintf(stdout, "%s%zu", i == 0 ? "" : ",", recognition.tasks[i]);
152	        }
153	        (void)fprintf(stdout, "\n");
154	        status = 0;
155	    } else {
156	        Location location;
157	        if (recognition.error_position < markup.count)
158	            location = markup.tokens[recognition.error_position].loc;
159	        else
160	            location = end_location(input_source, input_length);
161	        (void)fprintf(stdout, "REJECT offset=%zu line=%zu column=%zu expected=%s\n",
162	                      location.offset, location.line, location.column, recognition.expected);
163	        status = 1;
164	    }
165	    markup_free(&markup);
166	    grammar_free(&grammar);
167	    free(grammar_source);
168	    free(input_source);
169	    return status;
170	}
