 50	static int vector_grow(ChartItem **data, size_t *capacity, size_t needed)
 51	{
 52	    size_t next = *capacity == 0 ? 16 : *capacity * 2;
 53	    ChartItem *grown;
 54	    if (*capacity >= needed)
 55	        return 0;
 56	    while (next < needed) {
 57	        if (next > ((size_t)-1) / 2)
 58	            return -1;
 59	        next *= 2;
 60	    }
 61	    grown = (ChartItem *)realloc(*data, next * sizeof(*grown));
 62	    if (grown == NULL)
 63	        return -1;
 64	    *data = grown;
 65	    *capacity = next;
 66	    return 0;
 67	}
