174	static int candidate_compare(const void *left, const void *right)
175	{
176	    const ChartItem *a = (const ChartItem *)left;
177	    const ChartItem *b = (const ChartItem *)right;
178	    if (a->rule != b->rule) return a->rule < b->rule ? -1 : 1;
179	    if (a->alternative != b->alternative) return a->alternative < b->alternative ? -1 : 1;
180	    if (a->dot != b->dot) return a->dot < b->dot ? -1 : 1;
181	    if (a->origin != b->origin) return a->origin < b->origin ? -1 : 1;
182	    return 0;
183	}
