554	void grammar_free(Grammar *grammar)
555	{
556	    size_t i;
557	    for (i = 0; i < grammar->rule_count; i++) {
558	        size_t j;
559	        Rule *rule = &grammar->rules[i];
560	        free(rule->name);
561	        for (j = 0; j < rule->count; j++) {
562	            size_t k;
563	            for (k = 0; k < rule->alternatives[j].count; k++)
564	                free(rule->alternatives[j].symbols[k].text);
565	            free(rule->alternatives[j].symbols);
566	        }
567	        free(rule->alternatives);
568	    }
569	    free(grammar->rules);
570	    free(grammar->start_name);
571	    memset(grammar, 0, sizeof(*grammar));
572	}
